r{display:grid;grid-template-columns:auto 1fr auto;gap:18px;align-items:center;margin:26px 0;padding:22px;border:1px solid rgba(198,149,45,.35);border-radius:18px;background:linear-gradient(135deg,#fffaf0,#fff);box-shadow:0 14px 34px rgba(22,52,91,.08)}.status-icon{display:grid;place-items:center;width:54px;height:54px;border-radius:16px;color:#fff;background:linear-gradient(145deg,var(--gold),#e0ae47);font-size:25px;font-weight:900}.status-banner h2{margin:0;color:var(--navy);font-size:20px}.status-banner p{margin:6px 0 0;color:var(--muted);font-size:13px;line-height:1.5}.status-pill{padding:8px 11px;border-radius:999px;color:#80520c;background:#fff0c9;font-size:10px;font-weight:900;letter-spacing:.06em;text-transform:uppercase}.actions{display:flex;flex-wrap:wrap;gap:10px;margin:22px 0 30px}.action{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:11px 16px;border-radius:11px;color:#fff;background:var(--navy);box-shadow:0 9px 20px rgba(22,52,91,.16);font-size:12px;font-weight:900;text-decoration:none}.action.secondary{color:var(--navy);border:1px solid var(--line);background:#fff;box-shadow:none}.action:hover{transform:translateY(-1px)}.facts{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:30px}.fact{padding:17px;border:1px solid var(--line);border-radius:14px;background:#fff;box-shadow:0 9px 24px rgba(22,52,91,.06)}.fact span{display:block;color:var(--muted);font-size:10px;font-weight:900;letter-spacing:.07em;text-transform:uppercase}.fact strong{display:block;margin-top:8px;color:var(--navy);font-size:15px;line-height:1.35}.section-head{margin:34px 0 15px}.section-head h2{margin:0;color:var(--navy);font-size:25px}.section-head p{margin:7px 0 0;color:var(--muted);font-size:13px;line-height:1.55}.chapters{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.chapter{position:relative;min-height:150px;padding:18px 18px 18px 55px;border:1px solid var(--line);border-radius:15px;background:#fff;box-shadow:0 10px 26px rgba(22,52,91,.06)}.chapter b{position:absolute;top:18px;left:17px;display:grid;place-items:center;width:28px;height:28px;border-radius:9px;color:#fff;background:var(--teal);font-size:11px}.chapter h3{margin:0;color:var(--navy);font-size:15px;line-height:1.3}.chapter p{margin:8px 0 0;color:var(--muted);font-size:11px;line-height:1.5}.workflow{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.stage{padding:18px;border-radius:14px;border:1px solid var(--line);background:#fff}.stage i{display:block;width:12px;height:12px;margin-bottom:12px;border-radius:50%;background:#b8c5cf}.stage.done i{background:var(--teal)}.stage.current{border-color:rgba(198,149,45,.5);background:#fffaf0}.stage.current i{background:var(--gold);box-shadow:0 0 0 6px rgba(198,149,45,.15)}.stage strong{display:block;color:var(--navy);font-size:13px}.stage span{display:block;margin-top:6px;color:var(--muted);font-size:11px;line-height:1.45}.viewer{overflow:hidden;margin-top:16px;border:1px solid var(--line);border-radius:18px;background:#fff;box-shadow:0 16px 38px rgba(22,52,91,.09)}.viewer-head{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:15px 18px;border-bottom:1px solid var(--line)}.viewer-head strong{color:var(--navy);font-size:14px}.viewer-head span{color:var(--amber);font-size:10px;font-weight:900;text-transform:uppercase}.viewer iframe{display:block;width:100%;height:820px;border:0;background:#eef3f6}.notice{margin-top:14px;padding:15px 17px;border-left:4px solid var(--gold);border-radius:9px;color:#5c6470;background:#fff8e8;font-size:12px;line-height:1.55}@@media(max-width:1000px){.facts,.workflow{grid-template-columns:repeat(2,minmax(0,1fr))}.chapters{grid-template-columns:repeat(2,minmax(0,1fr))}}@@media(max-width:760px){.shell{grid-template-columns:1fr}.sidebar{position:static;height:auto}.content{padding:25px 18px 40px}.status-banner{grid-template-columns:auto 1fr}.status-pill{grid-column:1/-1;width:max